CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, totp_secret text NOT NULL, last_totp_step bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS singleton_admin ON admins((true));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits(key text PRIMARY KEY, attempts int NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY, name text NOT NULL, role text NOT NULL CHECK(role IN ('station','gateway')), token_hash text UNIQUE, enrollment_hash text UNIQUE, enrollment_expires timestamptz, last_seen timestamptz, telemetry jsonb NOT NULL DEFAULT '{}', capabilities jsonb NOT NULL DEFAULT '[]', revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS commands(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','leased','succeeded','failed','expired')), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, leased_at timestamptz, lease_hash text, completed_at timestamptz, result text, source text NOT NULL DEFAULT 'admin');
CREATE INDEX IF NOT EXISTS commands_queue ON commands(device_id,status,created_at);
CREATE TABLE IF NOT EXISTS credentials(integration text PRIMARY KEY CHECK(integration IN ('deepfreeze','handycafe','steam')), encrypted text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schedules(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), name text NOT NULL, kind text NOT NULL CHECK(kind='steam_update'), payload jsonb NOT NULL, weekday int NOT NULL CHECK(weekday BETWEEN 0 AND 6), hour int NOT NULL CHECK(hour BETWEEN 0 AND 23), minute int NOT NULL CHECK(minute BETWEEN 0 AND 59), enabled boolean NOT NULL DEFAULT true, last_slot text);
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target text, created_at timestamptz NOT NULL DEFAULT now());
